export const metadata:Metadata={title:'隐私政策',description:'Marghera Venice Apartments 网站个人数据处理说明。',alternates:{canonical:'/zh/privacy-policy',languages:{'it-IT': '/privacy-policy', 'en-GB': '/en/privacy-policy', 'de-DE': '/de/privacy-policy', 'fr-FR': '/fr/privacy-policy', 'es-ES': '/es/privacy-policy', 'zh-CN': '/zh/privacy-policy', 'x-default': '/privacy-policy'}},openGraph:{title:'隐私政策',description:'Marghera Venice Apartments 网站个人数据处理说明。',url:'/zh/privacy-policy',locale:'zh_CN',type:'website',images:['/images/home-rialto-vincenzo-landino.webp']},twitter:{card:'summary_large_image',title:'隐私政策',description:'Marghera Venice Apartments 网站个人数据处理说明。',images:['/images/home-rialto-vincenzo-landino.webp']}};
const sections=[{'title': '数据控制者与联系方式', 'text': '网站及通过所列渠道收到的联系数据由 Marghera Venice Apartments 负责处理。\n联系方式：+39 351 446 2261 · info@margheraveniceapartments.com。'}, {'title': '处理的数据与目的', 'text': '访问网站时，托管/CDN 服务商可能处理保障安全、页面传输和服务运行所必需的技术数据。网站本身没有内置联系表单。如果您通过电话、电子邮件、WhatsApp 或微信联系我们，我们会处理您主动提供的信息，用于回复咨询、提供住宿信息，并在需要时处理预订前事项或住宿服务。'}, {'title': '处理依据', 'text': '有关房态、预订和住宿的咨询，为应您的请求采取合同前措施或履行由此产生的合同关系而处理。为保障网站安全和正常运行所必需的技术数据，基于维护安全、可用服务的合法利益进行处理。'}, {'title': '接收方与外部服务', 'text': '数据可能由网站运行所必需的技术服务商处理；在您同意后，Google 还可能为提供 Google Analytics 4 而处理相关数据。只有当您主动打开相应链接时，您选择启用的 WhatsApp、微信、Instagram、Facebook 或其他外部信息网站才可能进一步处理数据，并适用各自的隐私政策。'}, {'title': 'Analytics 与同意', 'text': '在您同意后，我们使用 Google Analytics 4 获取网站使用情况的汇总统计，包括页面浏览量以及 WhatsApp 或电子邮件链接点击等交互。您同意之前不会加载 Analytics 标签，广告相关功能保持关闭。您可以通过页脚中的 Cookie 设置随时修改或撤回选择。'}, {'title': '保存期限', 'text': '咨询数据仅在处理联系所需期间保存；如产生预订或法定义务，则按适用法律要求的期限保存。安全相关技术数据仅按必要期限及技术服务商设置保存。'}, {'title': '您的权利', 'text': '在《欧盟通用数据保护条例》(EU) 2016/679 规定的情况下，您可通过上述联系方式申请访问、更正、删除、限制处理、反对处理及数据可携带，并有权向有管辖权的数据保护监管机构提出投诉。'}, {'title': '更新', 'text': '当网站功能、技术服务商或数据处理方式发生变化时，本政策会相应更新。最后更新：2026年8月21日。'}];
